<?php $threads = ClientApi::data($api->request('GET','api/support/threads')); ?>
<section class="grid two-col"><article class="panel"><h2 class="section-title">Contacter l’assistance</h2><p class="row-meta">Décrivez votre demande. Elle sera conservée dans votre espace et transmise à l’administration.</p><form method="post" class="form-grid"><?= client_csrf_field() ?><input type="hidden" name="action" value="support_create"><div class="field full"><label for="subject">Sujet</label><input id="subject" name="subject" maxlength="160" required></div><div class="field full"><label for="message">Votre message</label><textarea id="message" name="message" maxlength="5000" required></textarea></div><div class="form-actions"><button class="btn" type="submit">Envoyer la demande</button></div></form></article><article class="panel"><h2 class="section-title">Mes demandes</h2><?php if (!$threads): ?><div class="empty"><div class="empty-icon">✉</div><h3>Aucune conversation</h3><p>Les réponses de l’assistance apparaîtront ici.</p></div><?php else: ?><div class="list"><?php foreach ($threads as $t): ?><a class="list-row" href="?page=messages&amp;id=<?= (int)$t['id'] ?>"><div><div class="row-title"><?= client_h($t['subject'] ?? '') ?></div><div class="row-meta">Mise à jour <?= client_h(client_format_date($t['updated_at'] ?? null)) ?></div></div><?= client_status_badge((string)($t['status'] ?? 'ouvert')) ?></a><?php endforeach; ?></div><?php endif; ?></article></section>
<?php if (!empty($_GET['id']) && filter_var($_GET['id'],FILTER_VALIDATE_INT)): $thread = ClientApi::data($api->request('GET','api/support/threads/' . (int)$_GET['id'])); ?><section class="panel" style="margin-top:18px"><h2 class="section-title"><?= client_h($thread['subject'] ?? 'Conversation') ?> <?= client_status_badge((string)($thread['status'] ?? 'ouvert')) ?></h2><?php foreach (($thread['messages'] ?? []) as $m): ?><div class="message <?= ($m['sender_role'] ?? '') === 'Sadmin' ? 'admin' : '' ?>"><div class="message-meta"><?= client_h(($m['sender_role'] ?? '') === 'Sadmin' ? 'Assistance' : 'Vous') ?> · <?= client_h(client_format_date($m['created_at'] ?? null)) ?></div><?= nl2br(client_h($m['body'] ?? '')) ?></div><?php endforeach; ?><?php if (($thread['status'] ?? '') !== 'resolu'): ?><form method="post" class="form-grid" style="margin-top:16px"><?= client_csrf_field() ?><input type="hidden" name="action" value="support_reply"><input type="hidden" name="id" value="<?= (int)$thread['id'] ?>"><div class="field full"><label for="reply">Votre réponse</label><textarea id="reply" name="message" maxlength="5000" required></textarea></div><div class="form-actions"><button class="btn" type="submit">Répondre</button></div></form><?php endif; ?></section><?php endif; ?>
